-4170-aa31-835ab822fb2b', '9fd1d487-17b5-4cc1-aaef-1f835115bcfe'),\n  ('422047a4-b3c9-4cfc-b903-ebfd3f7135d3', '9fd1d487-17b5-4cc1-aaef-1f835115bcfe'),\n  ('9c8839c4-23d0-4ec1-b4b9-bb3dd380a714', '1717ebc5-4cd0-4ef2-b670-200d82756d5b'),\n  ('67e79d11-8772-4962-95c9-f747ee111e21', '1717ebc5-4cd0-4ef2-b670-200d82756d5b'),\n  ('4b93141d-4306-4cf7-87ca-5985faae9541', '9fd1d487-17b5-4cc1-aaef-1f835115bcfe'),\n  ('af291e73-b620-4e93-8673-cd201a491bfc', '9fd1d487-17b5-4cc1-aaef-1f835115bcfe'),\n  ('77f1fe06-c65b-42ac-99a5-bf2ce27bb10b', '9fd1d487-17b5-4cc1-aaef-1f835115bcfe');\n\n-- [B] ASSERT MAPPING TABLE ROW COUNTS AND FOREIGN KEYS\nDO $$\nDECLARE\n  map_count INT;\n  prod_match_count INT;\n  invalid_cat_count INT;\nBEGIN\n  SELECT count(*) INTO map_count FROM _category_mapping;\n  IF map_count != 192 THEN\n    RAISE EXCEPTION 'Expected 192 mapping rows, got %', map_count;\n  END IF;\n  \n  SELECT count(*) INTO prod_match_count FROM _category_mapping m JOIN products p ON m.product_id = p.id;\n  IF prod_match_count != 192 THEN\n    RAISE EXCEPTION 'Expected 192 matched products, got %', prod_match_count;\n  END IF;\n  \n  SELECT count(*) INTO invalid_cat_count FROM _category_mapping m LEFT JOIN categories c ON m.destination_category_id = c.id WHERE c.id IS NULL;\n  IF invalid_cat_count > 0 THEN\n    RAISE EXCEPTION 'Found % invalid destination category IDs', invalid_cat_count;\n  END IF;\nEND $$;\n\n-- [C] RENAME CATEGORY AND ASSERT\nUPDATE categories \nSET name = 'Vegetables & Fruits' \nWHERE name = 'Fruits & Vegetables' AND id = 'c0000000-0000-0000-0000-000000000001';\n\nDO $$\nDECLARE\n  veg_count INT;\nBEGIN\n  SELECT count(*) INTO veg_count FROM categories WHERE name = 'Vegetables & Fruits';\n  IF veg_count != 1 THEN\n    RAISE EXCEPTION 'Expected exactly 1 Vegetables & Fruits category, got %', veg_count;\n  END IF;\nEND $$;\n\n-- [D] APPLY UPDATE FROM TEMP MAPPING\nUPDATE products p\nSET category_id = m.destination_category_id\nFROM _category_mapping m\nWHERE p.id = m.product_id;\n\n-- [E] ZERO PRODUCTS REFERENCE OBSOLETE CATEGORIES\nDO $$ \nDECLARE \n  obsolete_count INT;\nBEGIN\n  SELECT count(*) INTO obsolete_count FROM products WHERE category_id IN (\n    'c0000000-0000-0000-0000-000000000003',\n    'c0000000-0000-0000-0000-000000000004',\n    'c0000000-0000-0000-0000-000000000005',\n    'c0000000-0000-0000-0000-000000000006'\n  );\n  IF obsolete_count > 0 THEN\n    RAISE EXCEPTION 'Products still reference obsolete categories';\n  END IF;\nEND $$;\n\n-- [F] DELETE OBSOLETE CATEGORIES AND ASSERT\nDELETE FROM categories WHERE id IN (\n  'c0000000-0000-0000-0000-000000000003',\n  'c0000000-0000-0000-0000-000000000004',\n  'c0000000-0000-0000-0000-000000000005',\n  'c0000000-0000-0000-0000-000000000006'\n);\n\nDO $$\nDECLARE\n  obs_cat_count INT;\nBEGIN\n  SELECT count(*) INTO obs_cat_count FROM categories WHERE id IN (\n    'c0000000-0000-0000-0000-000000000003',\n    'c0000000-0000-0000-0000-000000000004',\n    'c0000000-0000-0000-0000-000000000005',\n    'c0000000-0000-0000-0000-000000000006'\n  );\n  IF obs_cat_count > 0 THEN\n    RAISE EXCEPTION 'Failed to delete % obsolete categories', obs_cat_count;\n  END IF;\nEND $$;\n\n-- [G] EXACT FINAL CATEGORY SET ASSERTION\nDO $$\nDECLARE\n  missing_names VARCHAR;\n  extra_names VARCHAR;\n  distinct_cat_count INT;\nBEGIN\n  IF (SELECT count(*) FROM categories) != 26 THEN\n    RAISE EXCEPTION 'Expected exactly 26 categories, found %', (SELECT count(*) FROM categories);\n  END IF;\n  SELECT count(distinct name) INTO distinct_cat_count FROM categories;\n  IF distinct_cat_count != 26 THEN\n    RAISE EXCEPTION 'Expected 26 distinct category names, got %', distinct_cat_count;\n  END IF;\nEND $$;\n